const cfg = $('Pipeline Config').first().json;
const response = $input.first().json;
const accounts = Array.isArray(response.data) ? response.data : [];
const configured = String(cfg.meta_ad_account_id || '').replace(/^act_/, '');
const active = accounts.filter((item) => Number(item.account_status) === 1);
const selected = configured
  ? accounts.find((item) => String(item.id).replace(/^act_/, '') === configured)
  : active.find((item) => String(item.name || '').toLowerCase().includes('press burger')) || (active.length === 1 ? active[0] : null);

if (!selected) {
  throw new Error('Unable to resolve the Press Burger Meta ad account. Available active accounts: ' + active.map((item) => item.name + ' (' + item.id + ')').join(', '));
}

return [{ json: {
  ...cfg,
  meta_ad_account_id: String(selected.id).startsWith('act_') ? String(selected.id) : 'act_' + selected.id,
  meta_ad_account_name: selected.name || null,
  currency: selected.currency || 'USD',
  meta_timezone: selected.timezone_name || cfg.timezone
} }];

const cfg = $('Resolve Press Burger Ad Account').first().json;
const campaignRows = $('Meta Insights - Campaign Daily').first().json.data || [];
const adInsightRows = $('Meta Insights - Ad Lifetime').first().json.data || [];
const adMetadataRows = $('Meta - Ad Creative Metadata').first().json.data || [];

function num(value) {
  const parsed = Number(value ?? 0);
  return Number.isFinite(parsed) ? parsed : 0;
}

const purchaseTypes = [
  'offsite_conversion.fb_pixel_purchase',
  'onsite_web_purchase',
  'web_in_store_purchase',
  'omni_purchase',
  'purchase'
];

function purchaseMetric(entries) {
  const values = Array.isArray(entries) ? entries : [];
  for (const actionType of purchaseTypes) {
    const match = values.find((item) => item.action_type === actionType);
    if (match) return num(match.value);
  }
  return 0;
}

function metrics(row) {
  const spend = num(row.spend);
  const revenue = purchaseMetric(row.action_values);
  const conversions = purchaseMetric(row.actions);
  const clicks = num(row.inline_link_clicks || row.clicks);
  const impressions = num(row.impressions);
  return {
    spend,
    revenue,
    conversions: Math.round(conversions),
    clicks: Math.round(clicks),
    impressions: Math.round(impressions),
    cpa: conversions > 0 ? spend / conversions : null,
    roas: spend > 0 ? revenue / spend : null,
    ctr: impressions > 0 ? clicks / impressions : null,
    cpc: clicks > 0 ? spend / clicks : null
  };
}

const updatedAt = new Date().toISOString();
const campaign_daily_performance = campaignRows.map((row) => {
  const values = metrics(row);
  return {
    client_id: cfg.client_id,
    date: row.date_start,
    platform: 'Meta Ads',
    channel: 'Paid Social',
    campaign_id: String(row.campaign_id || ''),
    campaign_name: row.campaign_name || null,
    ...values,
    store_visits: null,
    wasted_spend: values.conversions > 0 ? 0 : values.spend,
    updated_at: updatedAt
  };
}).filter((row) => row.date && row.campaign_id);

const dailyMap = new Map();
for (const row of campaign_daily_performance) {
  const current = dailyMap.get(row.date) || {
    client_id: cfg.client_id,
    date: row.date,
    platform: 'Meta Ads',
    channel: 'Paid Social',
    spend: 0,
    revenue: 0,
    conversions: 0,
    store_visits: null,
    clicks: 0,
    impressions: 0,
    updated_at: updatedAt
  };
  for (const field of ['spend', 'revenue', 'conversions', 'clicks', 'impressions']) current[field] += num(row[field]);
  dailyMap.set(row.date, current);
}

const daily_performance = [...dailyMap.values()].map((row) => ({
  ...row,
  conversions: Math.round(row.conversions),
  clicks: Math.round(row.clicks),
  impressions: Math.round(row.impressions),
  cpa: row.conversions > 0 ? row.spend / row.conversions : null,
  roas: row.spend > 0 ? row.revenue / row.spend : null,
  ctr: row.impressions > 0 ? row.clicks / row.impressions : null,
  cpc: row.clicks > 0 ? row.spend / row.clicks : null
}));

const creativeByAd = new Map(adMetadataRows.map((row) => [String(row.id), row]));

function firstText(values) {
  const first = Array.isArray(values) ? values[0] : null;
  return first?.text || first?.name || null;
}

function creativeDetails(ad) {
  const creative = ad?.creative || {};
  const story = creative.object_story_spec || {};
  const link = story.link_data || story.template_data || {};
  const feed = creative.asset_feed_spec || {};
  const headline = creative.title || link.name || firstText(feed.titles) || ad?.name || null;
  const description = creative.body || link.message || firstText(feed.bodies) || null;
  const finalUrl = creative.link_url || link.link || firstText(feed.link_urls) || null;
  const imageUrl = creative.image_url || link.picture || feed.images?.[0]?.url || null;
  return { creative, headline, description, finalUrl, imageUrl };
}

const ad_lifetime_performance = adInsightRows.map((row) => {
  const ad = creativeByAd.get(String(row.ad_id)) || {};
  const detail = creativeDetails(ad);
  return {
    client_id: cfg.client_id,
    platform: 'Meta Ads',
    channel: 'Paid Social',
    campaign_id: String(row.campaign_id || ad.campaign?.id || '') || null,
    campaign_name: row.campaign_name || ad.campaign?.name || null,
    ad_group_id: String(row.adset_id || ad.adset?.id || '') || null,
    ad_group_name: row.adset_name || ad.adset?.name || null,
    ad_id: String(row.ad_id || ad.id || ''),
    ad_name: row.ad_name || ad.name || null,
    ad_type: 'META_AD',
    ad_status: ad.effective_status || ad.status || null,
    final_url: detail.finalUrl,
    creative_id: detail.creative.id ? String(detail.creative.id) : null,
    creative_name: detail.creative.name || null,
    creative_preview_url: null,
    creative_preview_type: null,
    creative_headline: detail.headline,
    creative_description: detail.description,
    creative_image_url: detail.imageUrl || detail.creative.thumbnail_url || null,
    asset_group_id: String(row.adset_id || ad.adset?.id || '') || null,
    asset_group_name: row.adset_name || ad.adset?.name || null,
    ...metrics(row),
    updated_at: updatedAt
  };
}).filter((row) => row.ad_id);

function assertUnique(rows, keyFields, label) {
  const seen = new Set();
  for (const row of rows) {
    const key = keyFields.map((field) => String(row[field] ?? '')).join('|');
    if (seen.has(key)) throw new Error(label + ' contains duplicate conflict key: ' + key);
    seen.add(key);
  }
}

assertUnique(daily_performance, ['client_id', 'date', 'platform', 'channel'], 'daily_performance');
assertUnique(campaign_daily_performance, ['client_id', 'date', 'platform', 'campaign_id'], 'campaign_daily_performance');
assertUnique(ad_lifetime_performance, ['client_id', 'platform', 'ad_id'], 'ad_lifetime_performance');

return [{ json: {
  client_id: cfg.client_id,
  client_name: cfg.client_name,
  meta_ad_account_id: cfg.meta_ad_account_id,
  meta_ad_account_name: cfg.meta_ad_account_name,
  date_start: cfg.date_start,
  date_end: cfg.date_end,
  datasets: [
    { table: 'daily_performance', on_conflict: 'client_id,date,platform,channel', rows: daily_performance },
    { table: 'campaign_daily_performance', on_conflict: 'client_id,date,platform,campaign_id', rows: campaign_daily_performance },
    { table: 'ad_lifetime_performance', on_conflict: 'client_id,platform,ad_id', rows: ad_lifetime_performance }
  ],
  counts: {
    daily_performance: daily_performance.length,
    campaign_daily_performance: campaign_daily_performance.length,
    ad_lifetime_performance: ad_lifetime_performance.length
  }
} }];

const normalized = $input.first().json;
return normalized.datasets
  .filter((dataset) => Array.isArray(dataset.rows) && dataset.rows.length > 0)
  .map((dataset) => ({ json: {
    ...dataset,
    client_name: normalized.client_name,
    meta_ad_account_name: normalized.meta_ad_account_name,
    date_start: normalized.date_start,
    date_end: normalized.date_end,
    counts: normalized.counts
  } }));
